def sum_naturals(n: int) -> int:
    """Sum of the first n naturals 1 + 2 + ... + n; equals n*(n+1)//2."""
    return n * (n + 1) // 2

def sum_odd(n: int) -> int:
    """Sum of the first n odd numbers; equals n*n."""
    return n * n

def sum_even(n: int) -> int:
    """Sum of the first n even numbers; equals n*(n+1)."""
    return n * (n + 1)

def add_commutative(a: int, b: int) -> bool:
    """Checks a + b == b + a."""
    return a + b == b + a

def mul_commutative(a: int, b: int) -> bool:
    """Checks a * b == b * a."""
    return a * b == b * a

def at_most_double(n: int) -> bool:
    """Checks n <= n + n."""
    return n <= n + n

def halve_double(n: int) -> bool:
    """Checks 2 * (n // 2) + n % 2 == n."""
    return 2 * (n // 2) + n % 2 == n

def is_even_or_odd(n: int) -> bool:
    """Checks n % 2 is 0 or 1."""
    return n % 2 in (0, 1)

def remainder_below_two(n: int) -> bool:
    """Checks n % 2 < 2."""
    return n % 2 < 2
